// ▼▼▼ 1. 型定義 (Type Definitions) ▼▼▼

// data.ts

export type QuestionType = 
  | "reading" 
  | "vocabulary" 
  | "grammar" 
  | "tashkeel" 
  | "orthography" 
  | "grammar_advanced"
  | "listening"       
  | "grammar_basic";  

export type QuizQuestion = {
  id?: number; 
  type: QuestionType;
  text: string;
  options: string[];
  correctIndex: number;
  explanation: string;
};

export type Vocab = {
  word: string;
  meaning: string;
};

// ★★★ 追加: 重要表現の型定義 ★★★
export type KeyExpression = {
  phrase: string;
  explanation: string;
  reading?: string; // カタカナ読みや発音記号など
};

export type Sentence = {
  arabic: string;
  japanese: string;
  speaker?: string; // 会話形式の場合に話者ラベル
  note?: string;    // 文法や重要表現の解説用
};

export type Article = {
  id: number;
  title: string;
  category: string;
  // "Poetry" をレベルに追加
  level: "初級" | "会話" | "中級" | "上級" | "文法" | "Poetry"; 
  
  contentVoweled: string;
  contentPlain: string;
  
  vocabList: Vocab[];
  questions: QuizQuestion[];
  sentences: Sentence[]; 
  
  // ★★★ 追加: 重要表現リスト（オプショナル） ★★★
  keyExpressions?: KeyExpression[];

  // ▼ 画像・動画用（オプショナル）
  videoUrl?: string;     
  imageUrls?: string[];  
};

